  "/lib/components/svforge/ui/Logo.svelte": "<script lang=\"ts\">\n\timport { cn } from '$lib/utils/cn';\n\n\tinterface Props {\n\t\tclass?: string;\n\t}\n\n\tlet { class: className = '' }: Props = $props();\n</script>\n\n<span class={cn('logo text-xl font-extrabold', className)}>SVForge</span>\n\n<style>\n\t@keyframes metalFlow {\n\t\t0% {\n\t\t\tbackground-position: 0% 50%;\n\t\t}\n\t\t50% {\n\t\t\tbackground-position: 100% 50%;\n\t\t}\n\t\t100% {\n\t\t\tbackground-position: 0% 50%;\n\t\t}\n\t}\n\t.logo {\n\t\tfont-family: 'Space Grotesk Variable', sans-serif;\n\t\tcolor: transparent;\n\t\tbackground: linear-gradient(\n\t\t\t45deg,\n\t\t\tvar(--color-secondary-200-800),\n\t\t\tvar(--color-secondary-500),\n\t\t\tvar(--color-secondary-600-400),\n\t\t\tvar(--color-secondary-200-800)\n\t\t);\n\t\tbackground-size: 200% 200%;\n\t\t-webkit-background-clip: text;\n\t\tbackground-clip: text;\n\t\tletter-spacing: 0.05em;\n\t\tanimation: metalFlow 5s ease-in-out infinite;\n\t\tfilter: drop-shadow(0 0 2px var(--color-secondary-200-800));\n\t}\n</style>\n",
  "/lib/components/svforge/ui/Seo.svelte": "<script lang=\"ts\">\n\timport { page } from '$app/state';\n\n\tinterface Props {\n\t\ttitle: string;\n\t\tdescription: string;\n\t\timage?: string;\n\t\turl?: string;\n\t\ttype?: string;\n\t}\n\n\tlet { title, description, image, url, type = 'website' }: Props = $props();\n\n\tconst resolvedUrl = $derived(url ?? page.url.href);\n\tconst twitterCard = $derived(image ? 'summary_large_image' : 'summary');\n</script>\n\n<svelte:head>\n\t<title>{title}</title>\n\t<meta name=\"description\" content={description} />\n\t<meta property=\"og:title\" content={title} />\n\t<meta property=\"og:description\" content={description} />\n\t<meta property=\"og:type\" content={type} />\n\t<meta property=\"og:url\" content={resolvedUrl} />\n\t{#if image}\n\t\t<meta property=\"og:image\" content={image} />\n\t{/if}\n\t<meta name=\"twitter:card\" content={twitterCard} />\n\t<meta name=\"twitter:title\" content={title} />\n\t<meta name=\"twitter:description\" content={description} />\n\t{#if image}\n\t\t<meta name=\"twitter:image\" content={image} />\n\t{/if}\n</svelte:head>\n",
  "/lib/components/svforge/ui/Sitemap.ts": "interface SitemapEntry {\n\tpath: string;\n\tlastmod?: string;\n\tchangefreq?: string;\n\tpriority?: number;\n}\n\nexport function generateSitemap(baseUrl: string, routes: SitemapEntry[]): string {\n\tconst entries = routes\n\t\t.map((route) => {\n\t\t\tconst loc = `${baseUrl}${route.path}`;\n\t\t\tlet xml = `  <url>\\n    <loc>${loc}</loc>`;\n\t\t\tif (route.lastmod) xml += `\\n    <lastmod>${route.lastmod}</lastmod>`;\n\t\t\tif (route.changefreq) xml += `\\n    <changefreq>${route.changefreq}</changefreq>`;\n\t\t\tif (route.priority !== undefined) xml += `\\n    <priority>${route.priority}</priority>`;\n\t\t\txml += '\\n  </url>';\n\t\t\treturn xml;\n\t\t})\n\t\t.join('\\n');\n\n\treturn `<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n${entries}\n</urlset>`;\n}\n",
  "/lib/components/svforge/ui/Table.svelte": "<script lang=\"ts\">\n\timport { cn } from '$lib/utils/cn';\n\timport type { Snippet } from 'svelte';\n\timport type { HTMLAttributes } from 'svelte/elements';\n\n\tinterface Column {\n\t\tkey: string;\n\t\tlabel: string;\n\t\tclass?: string;\n\t}\n\n\tinterface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {\n\t\tcolumns: Column[];\n\t\trows: Record<string, unknown>[];\n\t\tclass?: string;\n\t\t/** Optional per-cell renderer for rich cells (avatar, badge, actions…). */\n\t\tchildren?: Snippet<[{ row: Record<string, unknown>; col: Column }]>;\n\t}\n\n\tlet { columns, rows, class: className = '', children, ...rest }: Props = $props();\n</script>\n\n<div class={cn('overflow-x-auto rounded-card border border-surface-200-800', className)} {...rest}>\n\t<table class=\"w-full\">\n\t\t<thead class=\"bg-surface-100-800\">\n\t\t\t<tr>\n\t\t\t\t{#each columns as col}\n\t\t\t\t\t<th class=\"px-element py-3 text-left text-sm font-semibold text-surface-500 {col.class}\">\n\t\t\t\t\t\t{col.label}\n\t\t\t\t\t</th>\n\t\t\t\t{/each}\n\t\t\t</tr>\n\t\t</thead>\n\t\t<tbody class=\"divide-y divide-surface-200-800\">\n\t\t\t{#each rows as row}\n\t\t\t\t<tr class=\"hover:bg-surface-50-900 transition-colors\">\n\t\t\t\t\t{#each columns as col}\n\t\t\t\t\t\t<td class=\"px-element py-3 text-sm {col.class}\">\n\t\t\t\t\t\t\t{#if children}\n\t\t\t\t\t\t\t\t{@render children({ row, col })}\n\t\t\t\t\t\t\t{:else}\n\t\t\t\t\t\t\t\t{String(row[col.key] ?? '')}\n\t\t\t\t\t\t\t{/if}\n\t\t\t\t\t\t</td>\n\t\t\t\t\t{/each}\n\t\t\t\t</tr>\n\t\t\t{/each}\n\t\t</tbody>\n\t</table>\n</div>\n",
  "/lib/components/svforge/ui/ThemeToggle.svelte": "<script lang=\"ts\">\n\timport * as m from '$lib/paraglide/messages.js';\n\timport Sun from 'phosphor-svelte/lib/Sun';\n\timport Moon from 'phosphor-svelte/lib/Moon';\n\timport { onMount } from 'svelte';\n\n\tinterface Props {\n\t\tclass?: string;\n\t}\n\n\tlet { class: className = '' }: Props = $props();\n\n\tlet isDark = $state(true);\n\n\tfunction applyMode(dark: boolean) {\n\t\tconst mode = dark ? 'dark' : 'light';\n\t\tdocument.documentElement.setAttribute('data-mode', mode);\n\t\tdocument.documentElement.style.colorScheme = mode;\n\t}\n\n\tonMount(() => {\n\t\tconst stored = localStorage.getItem('theme-mode');\n\t\tif (stored) {\n\t\t\t// User has a manual preference\n\t\t\tisDark = stored === 'dark';\n\t\t} else {\n\t\t\t// Follow system\n\t\t\tisDark = window.matchMedia('(prefers-color-scheme: dark)').matches;\n\t\t}\n\t\tapplyMode(isDark);\n\t});\n\n\tfunction toggle() {\n\t\tisDark = !isDark;\n\t\tapplyMode(isDark);\n\t\tlocalStorage.setItem('theme-mode', isDark ? 'dark' : 'light');\n\t}\n</script>\n\n<button\n\tonclick={toggle}\n\tclass=\"btn hover:preset-tonal-surface p-2 rounded-full {className}\"\n\taria-label={m.common_toggle_theme()}\n>\n\t{#if isDark}\n\t\t<Moon size={18} />\n\t{:else}\n\t\t<Sun size={18} />\n\t{/if}\n</button>\n",
  "/lib/components/svforge/ui/index.ts": "export { default as Alert } from './Alert.svelte';\nexport { default as Card } from './Card.svelte';\nexport { default as Logo } from './Logo.svelte';\nexport { default as Seo } from './Seo.svelte';\nexport { default as Table } from './Table.svelte';\nexport { default as ThemeToggle } from './ThemeToggle.svelte';\nexport { generateSitemap } from './Sitemap';\n",
  "/lib/example.test.ts": "import { describe, it, expect } from 'vitest';\nimport { cn } from '$lib/utils/cn';\nimport { generateSitemap } from '$lib/components/svforge/ui/Sitemap';\n\ndescribe('cn utility', () => {\n\tit('merges class names', () => {\n\t\texpect(cn('px-4', 'py-2')).toBe('px-4 py-2');\n\t});\n\n\tit('handles conditional classes', () => {\n\t\texpect(cn('base', false && 'hidden', 'extra')).toBe('base extra');\n\t});\n\n\tit('merges conflicting tailwind classes', () => {\n\t\texpect(cn('px-4', 'px-8')).toBe('px-8');\n\t});\n});\n\ndescribe('generateSitemap', () => {\n\tit('generates valid sitemap XML', () => {\n\t\tconst xml = generateSitemap('https://example.com', [\n\t\t\t{ path: '/', priority: 1.0 },\n\t\t\t{ path: '/about', priority: 0.8 }\n\t\t]);\n\n\t\texpect(xml).toContain('<?xml version=\"1.0\"');\n\t\texpect(xml).toContain('<loc>https://example.com/</loc>');\n\t\texpect(xml).toContain('<loc>https://example.com/about</loc>');\n\t\texpect(xml).toContain('<priority>1</priority>');\n\t});\n\n\tit('omits optional fields when not provided', () => {\n\t\tconst xml = generateSitemap('https://example.com', [{ path: '/' }]);\n\t\texpect(xml).toContain('<loc>');\n\t\texpect(xml).not.toContain('<lastmod>');\n\t});\n});\n",
