export const dashboardFiles = {
  "/app.d.ts": "import type { User, Session } from 'better-auth/minimal';\n\n// See https://svelte.dev/docs/kit/types#app.d.ts\n// for information about these interfaces\ndeclare global {\n\tnamespace App {\n\t\tinterface Locals { user?: User; session?: Session }\n\n\t\t// interface Error {}\n\t\t// interface PageData {}\n\t\t// interface PageState {}\n\t\t// interface Platform {}\n\t}\n}\n\nexport {};\n",
  "/e2e/auth.test.ts": "import { test, expect } from '@playwright/test';\n\n/**\n * E2E tests for authentication flows.\n * Playwright is opt-in — install separately: bun add -D @playwright/test\n */\n\ntest.describe('authentication', () => {\n\ttest('redirects unauthenticated users to login', async ({ page }) => {\n\t\tawait page.goto('/dashboard');\n\t\tawait expect(page).toHaveURL(/\\/login/);\n\t});\n\n\ttest('shows login form', async ({ page }) => {\n\t\tawait page.goto('/login');\n\t\tawait expect(page.locator('input[type=\"email\"]')).toBeVisible();\n\t\tawait expect(page.locator('input[type=\"password\"]')).toBeVisible();\n\t});\n\n\ttest('shows validation feedback on empty submit', async ({ page }) => {\n\t\tawait page.goto('/login');\n\t\tawait page.click('button[type=\"submit\"]');\n\t\t// Browser-native validation or server-side error message\n\t\tawait expect(page.locator('input:invalid, [role=\"alert\"], .error')).toBeVisible({ timeout: 5000 });\n\t});\n\n\ttest('logs in with valid credentials', async ({ page }) => {\n\t\tawait page.goto('/login');\n\t\tawait page.fill('input[type=\"email\"]', 'admin@test.com');\n\t\tawait page.fill('input[type=\"password\"]', 'password123');\n\t\tawait page.click('button[type=\"submit\"]');\n\t\t// Should navigate away from /login after success\n\t\tawait expect(page).not.toHaveURL(/\\/login/);\n\t});\n});\n",
  "/e2e/navigation.test.ts": "import { test, expect } from '@playwright/test';\n\n/**\n * E2E tests for dashboard navigation and protected routes.\n * Playwright is opt-in — install separately: bun add -D @playwright/test\n */\n\ntest.describe('protected routes', () => {\n\ttest('admin page requires authentication', async ({ page }) => {\n\t\tawait page.goto('/admin');\n\t\tawait expect(page).toHaveURL(/\\/login/);\n\t});\n\n\ttest('settings page requires authentication', async ({ page }) => {\n\t\tawait page.goto('/admin/settings');\n\t\tawait expect(page).toHaveURL(/\\/login/);\n\t});\n});\n\ntest.describe('dashboard navigation (authenticated)', () => {\n\ttest.beforeEach(async ({ page }) => {\n\t\t// Login first\n\t\tawait page.goto('/login');\n\t\tawait page.fill('input[type=\"email\"]', 'admin@test.com');\n\t\tawait page.fill('input[type=\"password\"]', 'password123');\n\t\tawait page.click('button[type=\"submit\"]');\n\t\tawait page.waitForURL(/\\/dashboard|\\/admin/);\n\t});\n\n\ttest('can navigate to user management', async ({ page }) => {\n\t\tawait page.goto('/admin/users');\n\t\tawait expect(page.locator('table, [data-testid=\"user-list\"]')).toBeVisible();\n\t});\n\n\ttest('can navigate to settings', async ({ page }) => {\n\t\tawait page.goto('/admin/settings');\n\t\tawait expect(page.locator('h2, h3')).toContainText(/settings/i);\n\t});\n});\n",
  "/e2e/user-crud.test.ts": "import { test, expect } from '@playwright/test';\n\n/**\n * E2E tests for user CRUD flows and form feedback.\n * Playwright is opt-in — install separately: bun add -D @playwright/test\n */\n\ntest.describe('user management CRUD', () => {\n\ttest.beforeEach(async ({ page }) => {\n\t\tawait page.goto('/login');\n\t\tawait page.fill('input[type=\"email\"]', 'admin@test.com');\n\t\tawait page.fill('input[type=\"password\"]', 'password123');\n\t\tawait page.click('button[type=\"submit\"]');\n\t\tawait page.goto('/admin/users');\n\t});\n\n\ttest('displays user list table', async ({ page }) => {\n\t\tawait expect(page.locator('table')).toBeVisible();\n\t});\n\n\ttest('shows create user form feedback on validation error', async ({ page }) => {\n\t\t// Open create modal\n\t\tawait page.click('button:has-text(\"Add\"), button:has-text(\"Create\")');\n\t\t// Submit empty form\n\t\tawait page.click('button[type=\"submit\"]:has-text(\"Save\"), button[type=\"submit\"]:has-text(\"Create\")');\n\t\t// Expect feedback message\n\t\tawait expect(page.locator('[role=\"alert\"], .error, .text-error')).toBeVisible({ timeout: 5000 });\n\t});\n\n\ttest('can delete a user', async ({ page }) => {\n\t\t// Find a delete button (not the self-delete which is disabled)\n\t\tconst deleteButtons = page.locator('button[aria-label=\"Delete user\"]:not([disabled])');\n\t\tconst count = await deleteButtons.count();\n\t\tif (count > 0) {\n\t\t\tawait deleteButtons.first().click();\n\t\t\t// Confirm deletion\n\t\t\tawait page.click('button:has-text(\"Delete\"):not([aria-label])');\n\t\t\tawait expect(page.locator('[role=\"alert\"], .feedback, .text-success')).toBeVisible({ timeout: 5000 });\n\t\t}\n\t});\n\n\ttest('prevents self-deletion', async ({ page }) => {\n\t\t// The current admin's delete button should be disabled\n\t\tawait expect(page.locator('button[disabled][aria-label=\"Delete user\"]')).toBeVisible();\n\t});\n});\n",
  "/hooks.server.ts": "import type { Handle } from '@sveltejs/kit';\n// `building` is used to skip auth during prerender/build (SvelteKit builds pages statically).\nimport { building } from '$app/environment';\nimport { getTextDirection } from '$lib/paraglide/runtime';\nimport { paraglideMiddleware } from '$lib/paraglide/server';\nimport { auth } from '$lib/server/auth';\nimport { svelteKitHandler } from 'better-auth/svelte-kit';\n\n/**\n * Single composed handle (#280).\n *\n * Order matters:\n * 1. `paraglideMiddleware` negotiates the locale and rewrites `event.request`\n *    (cookie / accept-language handling).\n * 2. Better Auth reads the session from the REWRITTEN request and populates\n *    `locals.session` / `locals.user`; auth paths are routed to the auth\n *    handler, every other request resolves through the app.\n * 3. The Paraglide transform rewrites the `%paraglide.lang%` /\n *    `%paraglide.dir%` placeholders of app.html in the FINAL html — this must\n *    survive the composition: the #268 fix (composing handleBetterAuth) had\n *    dropped it, leaving the placeholders in the rendered HTML (#280).\n */\nexport const handle: Handle = async ({ event, resolve }) =>\n\tparaglideMiddleware(event.request, async ({ request, locale }) => {\n\t\tevent.request = request;\n\n\t\tconst session = await auth.api.getSession({ headers: event.request.headers });\n\t\tif (session) {\n\t\t\tevent.locals.session = session.session;\n\t\t\tevent.locals.user = session.user;\n\t\t}\n\n\t\treturn svelteKitHandler({\n\t\t\tevent,\n\t\t\tauth,\n\t\t\tbuilding,\n\t\t\t// svelteKitHandler calls resolve(event) with a single argument — the\n\t\t\t// Paraglide transform is applied here so the i18n placeholders of\n\t\t\t// app.html are rewritten in the final html.\n\t\t\tresolve: (event) =>\n\t\t\t\tresolve(event, {\n\t\t\t\t\ttransformPageChunk: ({ html }) =>\n\t\t\t\t\t\thtml\n\t\t\t\t\t\t\t.replace('%paraglide.lang%', locale)\n\t\t\t\t\t\t\t.replace('%paraglide.dir%', getTextDirection(locale))\n\t\t\t\t})\n\t\t});\n\t});\n",
  "/lib/client/auth.ts": "import { createAuthClient } from 'better-auth/svelte';\n\nexport const authClient = createAuthClient();\n",
  "/lib/components/svforge/layout/AdminLayout.svelte": "<script lang=\"ts\">\n\timport { cn } from '$lib/utils/cn';\n\timport * as m from '$lib/paraglide/messages.js';\n\timport type { Snippet } from 'svelte';\n\timport type { HTMLAttributes } from 'svelte/elements';\n\timport Users from 'phosphor-svelte/lib/Users';\n\timport Gear from 'phosphor-svelte/lib/Gear';\n\timport ChartBar from 'phosphor-svelte/lib/ChartBar';\n\timport SignOut from 'phosphor-svelte/lib/SignOut';\n\timport Menu from 'phosphor-svelte/lib/List';\n\timport X from 'phosphor-svelte/lib/X';\n\timport ThemeToggle from '$lib/components/svforge/ui/ThemeToggle.svelte';\n\n\ttype NavItem = { href: string; label: string; icon: typeof ChartBar };\n\n\tinterface Props extends HTMLAttributes<HTMLElement> {\n\t\titems?: NavItem[];\n\t\tcurrentPath?: string;\n\t\tuser?: { name: string; email: string } | null;\n\t\tonSignOut?: () => void;\n\t\tclass?: string;\n\t\tchildren: Snippet;\n\t}\n\n\tlet {\n\t\titems = [\n\t\t\t{ href: '/admin', label: m.layout_dashboard(), icon: ChartBar },\n\t\t\t{ href: '/admin/users', label: m.layout_users(), icon: Users },\n\t\t\t{ href: '/admin/settings', label: m.layout_settings(), icon: Gear }\n\t\t],\n\t\tcurrentPath = '',\n\t\tuser = null,\n\t\tonSignOut,\n\t\tclass: className,\n\t\tchildren\n\t}: Props = $props();\n\n\tlet collapsed = $state(false);\n\tlet mobileOpen = $state(false);\n\n\tfunction navClass(href: string) {\n\t\treturn cn(\n\t\t\t'flex items-center gap-3 px-3 py-2 rounded-card transition-colors',\n\t\t\tcurrentPath === href\n\t\t\t\t? 'bg-primary-100-900 text-primary-700-300'\n\t\t\t\t: 'hover:bg-surface-100-800 text-surface-600-400'\n\t\t);\n\t}\n</script>\n\n<div class={cn('flex min-h-screen', className)}>\n\t<!-- Desktop Sidebar -->\n\t<aside class=\"hidden lg:flex flex-col border-r border-surface-200-800 bg-surface-50-950 transition-all {collapsed ? 'w-16' : 'w-56'}\">\n\t\t<div class=\"flex items-center justify-between p-3 border-b border-surface-200-800\">\n\t\t\t{#if !collapsed}\n\t\t\t\t<a href=\"/admin\" class=\"text-lg font-heading font-bold text-primary-600-400\">{m.layout_admin()}</a>\n\t\t\t{/if}\n\t\t\t<button\n\t\t\t\tclass=\"btn preset-tonal-surface p-1 rounded\"\n\t\t\t\tonclick={() => (collapsed = !collapsed)}\n\t\t\t\taria-label={m.layout_toggle_sidebar()}\n\t\t\t\taria-expanded={!collapsed}\n\t\t\t>\n\t\t\t\t<Menu size={18} />\n\t\t\t</button>\n\t\t</div>\n\n\t\t<nav class=\"flex-1 p-2 space-y-1\" aria-label={m.layout_menu()}>\n\t\t\t{#each items as item}\n\t\t\t\t{@const Icon = item.icon}\n\t\t\t\t<a\n\t\t\t\t\thref={item.href}\n\t\t\t\t\tclass={navClass(item.href)}\n\t\t\t\t\taria-current={currentPath === item.href ? 'page' : undefined}\n\t\t\t\t>\n\t\t\t\t\t<Icon size={20} />\n\t\t\t\t\t{#if !collapsed}<span class=\"text-sm font-medium\">{item.label}</span>{/if}\n\t\t\t\t</a>\n\t\t\t{/each}\n\t\t</nav>\n\n\t\t<div class=\"p-2 border-t border-surface-200-800\">\n\t\t\t<ThemeToggle />\n\t\t</div>\n\t</aside>\n\n\t<!-- Main area -->\n\t<div class=\"flex-1 flex flex-col\">\n\t\t<!-- Top bar -->\n\t\t<header class=\"sticky top-0 z-50 bg-surface-50-950/80 backdrop-blur-md border-b border-surface-200-800 px-element py-3 flex items-center justify-between\">\n\t\t\t<div class=\"flex items-center gap-3\">\n\t\t\t\t<button class=\"lg:hidden btn preset-tonal-surface p-2 rounded\" onclick={() => (mobileOpen = !mobileOpen)} aria-label={m.layout_menu()} aria-expanded={mobileOpen}>\n\t\t\t\t\t{#if mobileOpen}<X size={20} />{:else}<Menu size={20} />{/if}\n\t\t\t\t</button>\n\t\t\t\t<h1 class=\"font-heading font-bold text-lg\">{m.layout_dashboard()}</h1>\n\t\t\t</div>\n\t\t\t<div class=\"flex items-center gap-3\">\n\t\t\t\t<ThemeToggle class=\"lg:hidden\" />\n\t\t\t\t{#if user}\n\t\t\t\t\t<span class=\"text-sm text-surface-500 hidden sm:block\">{user.name}</span>\n\t\t\t\t\t{#if onSignOut}\n\t\t\t\t\t\t<button class=\"btn preset-tonal-surface p-2 rounded\" onclick={onSignOut} aria-label={m.layout_sign_out()}>\n\t\t\t\t\t\t\t<SignOut size={18} />\n\t\t\t\t\t\t</button>\n\t\t\t\t\t{/if}\n\t\t\t\t{/if}\n\t\t\t</div>\n\t\t</header>\n\n\t\t<!-- Mobile sidebar overlay -->\n\t\t{#if mobileOpen}\n\t\t\t<button\n\t\t\t\ttype=\"button\"\n\t\t\t\taria-label={m.layout_close_menu()}\n\t\t\t\tclass=\"lg:hidden fixed inset-0 z-40 w-full bg-black/50 cursor-default\"\n\t\t\t\tonclick={() => (mobileOpen = false)}\n\t\t\t></button>\n\t\t\t<aside class=\"lg:hidden fixed left-0 top-0 z-50 h-full w-56 bg-surface-50-950 border-r border-surface-200-800 p-3 space-y-1 shadow-xl\" aria-label={m.layout_menu()}>\n\t\t\t\t\t{#each items as item}\n\t\t\t\t\t\t{@const Icon = item.icon}\n\t\t\t\t\t\t<a\n\t\t\t\t\t\t\thref={item.href}\n\t\t\t\t\t\t\tclass={navClass(item.href)}\n\t\t\t\t\t\t\taria-current={currentPath === item.href ? 'page' : undefined}\n\t\t\t\t\t\t\tonclick={() => (mobileOpen = false)}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t<Icon size={20} />\n\t\t\t\t\t\t\t<span class=\"text-sm font-medium\">{item.label}</span>\n\t\t\t\t\t\t</a>\n\t\t\t\t\t{/each}\n\t\t\t\t</aside>\n\t\t{/if}\n\n\t\t<!-- Content -->\n\t\t<main class=\"flex-1 p-group overflow-auto\">\n\t\t\t{@render children()}\n\t\t</main>\n\t</div>\n</div>\n",
  "/lib/components/svforge/ui/AvatarInitial.svelte": "<script lang=\"ts\">\n    import { cn } from '$lib/utils/cn';\n    interface Props {\n        name: string;\n        size?: 'sm' | 'md' | 'lg';\n        class?: string;\n    }\n    let { name, size = 'md', class: className }: Props = $props();\n    const initial = $derived(name[0]?.toUpperCase() ?? '?');\n    const sizes = { sm: 'w-7 h-7 text-xs', md: 'w-8 h-8 text-sm', lg: 'w-12 h-12 text-lg' };\n</script>\n\n<div class={cn('rounded-full bg-primary-100-900 flex items-center justify-center font-bold text-primary-600-400', sizes[size], className)}>\n    {initial}\n</div>\n",
  "/lib/components/svforge/ui/Feedback.svelte": "<script lang=\"ts\">\n    import { cn } from '$lib/utils/cn';\n    import * as m from '$lib/paraglide/messages.js';\n    import Check from 'phosphor-svelte/lib/Check';\n    import Warning from 'phosphor-svelte/lib/Warning';\n    import X from 'phosphor-svelte/lib/X';\n    interface Props {\n        type: 'success' | 'error';\n        message: string;\n        ondismiss?: () => void;\n        class?: string;\n    }\n    let { type, message, ondismiss, class: className }: Props = $props();\n</script>\n\n{#if message}\n<div class={cn('flex items-center gap-2 p-3 rounded-card', type === 'success' ? 'bg-success-100-900 text-success-700-300' : 'bg-error-100-900 text-error-300-700', className)}>\n    {#if type === 'success'}<Check size={18} />{:else}<Warning size={18} />{/if}\n    <span class=\"text-sm\">{message}</span>\n    {#if ondismiss}\n    <button class=\"ml-auto\" onclick={ondismiss} aria-label={m.common_dismiss()}><X size={14} /></button>\n    {/if}\n</div>\n{/if}\n",
  "/lib/components/svforge/ui/index.ts": "export { default as Alert } from './Alert.svelte';\nexport { default as Card } from './Card.svelte';\nexport { default as Logo } from './Logo.svelte';\nexport { default as Seo } from './Seo.svelte';\nexport { default as Table } from './Table.svelte';\nexport { default as ThemeToggle } from './ThemeToggle.svelte';\nexport { generateSitemap } from './Sitemap';\nexport { default as AvatarInitial } from './AvatarInitial.svelte';\nexport { default as Feedback } from './Feedback.svelte';\n",
  "/lib/server/admin-users.test.ts": "import { describe, it, expect, beforeAll, vi } from 'vitest';\n\n// $env/dynamic/private is a SvelteKit virtual module — not resolvable by the\n// bare vitest environment. Read DATABASE_URL from the project .env (created\n// by scripts/setup.sh before the CI runs `bun run test`).\nvi.mock('$env/dynamic/private', async () => {\n\tconst { readFileSync } = await import('node:fs');\n\tconst dotenv = readFileSync('.env', 'utf8');\n\tconst m = dotenv.match(/^DATABASE_URL=\"?([^\"\\n]+)\"?$/m);\n\treturn { env: { DATABASE_URL: m ? m[1].trim() : undefined } };\n});\n\nimport { createCredentialUser, DuplicateEmailError } from './admin-users';\nimport { verifyPassword } from 'better-auth/crypto';\nimport { db } from '$lib/server/db';\nimport { user, account, session } from '$lib/server/db/schema';\nimport { eq } from 'drizzle-orm';\n\n/**\n * Better Auth credential lifecycle (#292) — runs inside the dashboard\n * scaffold against the REAL PostgreSQL database (the CI profile performs a\n * drizzle push before `bun run test`).\n *\n * Proves the admin-created user matches the exact credential contract that\n * `signInEmail` expects: lowercase email lookup, `providerId: 'credential'`,\n * `accountId === userId`, scrypt hash verifiable by Better Auth, atomic\n * user+account creation, and NO session side-effect (the admin's own session\n * must survive the creation).\n */\nconst ADMIN = crypto.randomUUID();\nconst PASSWORD = 'password123';\n\nasync function cleanupUsers() {\n\t// FK cascades wipe account + session rows of every user.\n\tawait db.delete(user);\n}\n\ndescribe('admin-created credential users (#292)', () => {\n\tbeforeAll(async () => {\n\t\tawait cleanupUsers();\n\t\t// Seed the admin (first user = admin under the first-user-is-admin\n\t\t// pattern used by the dashboard).\n\t\tawait createCredentialUser({ name: 'Admin', email: 'admin@example.com', password: PASSWORD });\n\t});\n\n\tit('stores the email lowercased exactly like Better Auth sign-up (#292)', async () => {\n\t\tawait createCredentialUser({ name: 'Bob', email: 'Bob@Example.COM', password: PASSWORD });\n\n\t\tconst [byLowerCase] = await db.select({ id: user.id }).from(user).where(eq(user.email, 'bob@example.com')).limit(1);\n\t\texpect(byLowerCase).toBeDefined();\n\n\t\t// Mixed case never matches: signInEmail looks up email.toLowerCase(),\n\t\t// so a stored mixed-case email could never be logged into.\n\t\tconst [byMixedCase] = await db.select({ id: user.id }).from(user).where(eq(user.email, 'Bob@Example.COM')).limit(1);\n\t\texpect(byMixedCase).toBeUndefined();\n\t});\n\n\tit('creates the credential account per the BA contract: providerId credential, accountId = userId (#292)', async () => {\n\t\tconst created = await createCredentialUser({ name: 'Carol', email: 'carol@example.com', password: PASSWORD });\n\n\t\tconst [acc] = await db.select().from(account).where(eq(account.userId, created.id)).limit(1);\n\t\texpect(acc).toBeDefined();\n\t\texpect(acc.providerId).toBe('credential');\n\t\texpect(acc.accountId).toBe(created.id); // NOT the email — sign-up contract\n\t});\n\n\tit('hashes the password so Better Auth verifyPassword accepts it (#292)', async () => {\n\t\tconst created = await createCredentialUser({ name: 'Dan', email: 'dan@example.com', password: PASSWORD });\n\n\t\tconst [acc] = await db.select().from(account).where(eq(account.userId, created.id)).limit(1);\n\t\texpect(acc).toBeDefined();\n\t\t// password is nullable in the schema — the credential contract guarantees\n\t\t// it is set for credential accounts.\n\t\tconst hash = acc!.password!;\n\t\tconst ok = await verifyPassword({ hash, password: PASSWORD });\n\t\texpect(ok).toBe(true);\n\t\tconst ko = await verifyPassword({ hash: acc!.password!, password: 'wrong-password' });\n\t\texpect(ko).toBe(false);\n\t});\n\n\tit('duplicate email in ANY case is rejected and creates no second user (#292)', async () => {\n\t\tawait expect(\n\t\t\tcreateCredentialUser({ name: 'Bob Clone', email: 'BOB@example.com', password: PASSWORD })\n\t\t).rejects.toBeInstanceOf(DuplicateEmailError);\n\n\t\tconst count = await db.select({ id: user.id }).from(user).where(eq(user.email, 'bob@example.com'));\n\t\texpect(count).toHaveLength(1);\n\t});\n\n\tit('creates the user and account atomically — a failed insert leaves NO orphan user (#292)', async () => {\n\t\t// Race two identical creates: the pre-check may pass for both, so the\n\t\t// second insert hits the unique email index inside the transaction and\n\t\t// must roll back BOTH rows — never a user without its account.\n\t\tconst results = await Promise.allSettled([\n\t\t\tcreateCredentialUser({ name: 'Eve', email: 'eve@example.com', password: PASSWORD }),\n\t\t\tcreateCredentialUser({ name: 'Eve Clone', email: 'eve@example.com', password: PASSWORD })\n\t\t]);\n\t\texpect(results.filter((r) => r.status === 'fulfilled')).toHaveLength(1);\n\t\texpect(results.filter((r) => r.status === 'rejected')).toHaveLength(1);\n\n\t\tconst eves = await db.select({ id: user.id }).from(user).where(eq(user.email, 'eve@example.com'));\n\t\texpect(eves).toHaveLength(1);\n\t\tconst evesAccounts = await db.select().from(account).where(eq(account.userId, eves[0].id));\n\t\texpect(evesAccounts).toHaveLength(1);\n\t});\n\n\tit('never creates a session — the admin session is untouched (#292)', async () => {\n\t\tconst sessionsBefore = await db.select({ id: session.id }).from(session);\n\n\t\tawait createCredentialUser({ name: 'Frank', email: 'frank@example.com', password: PASSWORD });\n\n\t\tconst sessionsAfter = await db.select({ id: session.id }).from(session);\n\t\texpect(sessionsAfter).toHaveLength(sessionsBefore.length);\n\t});\n\n\tit('the creation helper uses a DB transaction (structural atomicity guard) (#292)', async () => {\n\t\tconst txSpy = vi.spyOn(db, 'transaction');\n\t\tawait createCredentialUser({ name: 'Grace', email: 'grace@example.com', password: PASSWORD });\n\t\texpect(txSpy).toHaveBeenCalled();\n\t\ttxSpy.mockRestore();\n\t});\n});\n",
  "/lib/server/admin-users.ts": "import { db } from '$lib/server/db';\nimport { user, account } from '$lib/server/db/schema';\nimport { eq } from 'drizzle-orm';\nimport { hashPassword } from 'better-auth/crypto';\n\n/**\n * Admin user creation — the ONLY supported way to create a credential user\n * from the dashboard (#292).\n *\n * WHY NOT `auth.api.signUpEmail`?\n * -------------------------------\n * `signUpEmail` sets a session cookie for the newly created user, which would\n * silently replace the current admin's session. Admin-created users must not\n * hijack the admin's browser session.\n *\n * Instead we reproduce the exact credential contract of Better Auth 1.4.x,\n * verified against the package sources (`api/routes/sign-up.mjs`,\n * `db/internal-adapter.mjs`):\n *\n *   - `email` is stored LOWERCASED — `findUserByEmail` (used by sign-in)\n *     always looks up `email.toLowerCase()`, so a mixed-case stored email can\n *     never be logged into.\n *   - `providerId` is `'credential'` and `accountId` is the USER id (NOT the\n *     email) — that is what `linkAccount` does in the real sign-up flow.\n *   - the password is hashed with the same scrypt `hashPassword` that\n *     Better Auth's default `password.hash` uses (`better-auth/crypto`),\n *     so `signInEmail` can verify it.\n *   - `emailVerified` defaults to `false`, exactly like sign-up.\n *\n * The user row and the credential account row are created in ONE transaction:\n * a user without its credential account could never sign in (orphan row), so\n * the two inserts must be atomic.\n *\n * This helper NEVER creates a session — the admin's own session is untouched.\n */\n\nexport class DuplicateEmailError extends Error {\n\tconstructor() {\n\t\tsuper('email already exists');\n\t\tthis.name = 'DuplicateEmailError';\n\t}\n}\n\nexport interface CreateCredentialUserInput {\n\tname: string;\n\temail: string;\n\tpassword: string;\n}\n\nexport async function createCredentialUser({\n\tname,\n\temail,\n\tpassword\n}: CreateCredentialUserInput): Promise<{ id: string; email: string }> {\n\tconst normalizedEmail = email.toLowerCase();\n\n\t// Duplicate check — case-insensitive, matching Better Auth's lookup.\n\tconst [existing] = await db\n\t\t.select({ id: user.id })\n\t\t.from(user)\n\t\t.where(eq(user.email, normalizedEmail))\n\t\t.limit(1);\n\tif (existing) {\n\t\tthrow new DuplicateEmailError();\n\t}\n\n\tconst hashedPassword = await hashPassword(password);\n\tconst userId = crypto.randomUUID();\n\n\ttry {\n\t\tawait db.transaction(async (tx) => {\n\t\t\tawait tx.insert(user).values({\n\t\t\t\tid: userId,\n\t\t\t\tname,\n\t\t\t\temail: normalizedEmail,\n\t\t\t\temailVerified: false,\n\t\t\t\tcreatedAt: new Date(),\n\t\t\t\tupdatedAt: new Date()\n\t\t\t});\n\n\t\t\tawait tx.insert(account).values({\n\t\t\t\tid: crypto.randomUUID(),\n\t\t\t\tuserId,\n\t\t\t\t// Contract: accountId === userId for credential accounts (#292).\n\t\t\t\taccountId: userId,\n\t\t\t\tproviderId: 'credential',\n\t\t\t\tpassword: hashedPassword,\n\t\t\t\tcreatedAt: new Date(),\n\t\t\t\tupdatedAt: new Date()\n\t\t\t});\n\t\t});\n\t} catch (error) {\n\t\tif (error instanceof DuplicateEmailError) throw error;\n\t\t// A race on the unique email index or any other DB failure must roll\n\t\t// back BOTH rows — the transaction guarantees the user is not orphaned.\n\t\tthrow new Error('failed to create user');\n\t}\n\n\treturn { id: userId, email: normalizedEmail };\n}\n",
  "/lib/server/admin.ts": "import { db } from '$lib/server/db';\nimport { user } from '$lib/server/db/schema';\nimport { asc } from 'drizzle-orm';\n\n/**\n * Check if a user is an admin.\n * \n * This template uses the \"first-user-is-admin\" pattern.\n * For multi-user scenarios, add a `role` column to the user schema\n * and check it here instead.\n */\n// Pattern: first-user-is-admin. The oldest user (by createdAt) is the admin.\n// For multi-role scenarios, add a `role` column to the user table and check it here.\nexport async function isAdmin(userId: string): Promise<boolean> {\n\tconst [firstUser] = await db.select({ id: user.id })\n\t\t.from(user)\n\t\t.orderBy(asc(user.createdAt))\n\t\t.limit(1);\n\treturn firstUser?.id === userId;\n}\n",
  "/lib/server/auth.ts": "import { betterAuth } from 'better-auth/minimal';\nimport { drizzleAdapter } from 'better-auth/adapters/drizzle';\nimport { sveltekitCookies } from 'better-auth/svelte-kit';\nimport { env } from '$env/dynamic/private';\nimport { getRequestEvent } from '$app/server';\nimport { db } from '$lib/server/db';\n\nexport const auth = betterAuth({\n\tbaseURL: env.ORIGIN,\n\tsecret: env.BETTER_AUTH_SECRET,\n\tdatabase: drizzleAdapter(db, { provider: 'pg' }),\n\temailAndPassword: { enabled: true },\n\tplugins: [\n\t\tsveltekitCookies(getRequestEvent) // make sure this is the last plugin in the array\n\t]\n});\n",
  "/lib/server/db/auth.schema.ts": "import { relations, sql } from 'drizzle-orm';\nimport { pgTable, text, integer, timestamp, boolean, index } from 'drizzle-orm/pg-core';\n\nexport const user = pgTable('user', {\n\tid: text('id').primaryKey(),\n\tname: text('name').notNull(),\n\temail: text('email').notNull().unique(),\n\temailVerified: boolean('email_verified').notNull().default(false),\n\timage: text('image'),\n\tcreatedAt: timestamp('created_at', { withTimezone: true })\n\t\t.default(sql`now()`)\n\t\t.notNull(),\n\tupdatedAt: timestamp('updated_at', { withTimezone: true })\n\t\t.default(sql`now()`)\n\t\t.$onUpdate(() => new Date())\n\t\t.notNull()\n});\n\nexport const session = pgTable(\n\t'session',\n\t{\n\t\tid: text('id').primaryKey(),\n\t\texpiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),\n\t\ttoken: text('token').notNull().unique(),\n\t\tcreatedAt: timestamp('created_at', { withTimezone: true })\n\t\t\t.default(sql`now()`)\n\t\t\t.notNull(),\n\t\tupdatedAt: timestamp('updated_at', { withTimezone: true })\n\t\t\t.default(sql`now()`)\n\t\t\t.$onUpdate(() => new Date())\n\t\t\t.notNull(),\n\t\tipAddress: text('ip_address'),\n\t\tuserAgent: text('user_agent'),\n\t\tuserId: text('user_id')\n\t\t\t.notNull()\n\t\t\t.references(() => user.id, { onDelete: 'cascade' })\n\t},\n\t(table) => [index('session_userId_idx').on(table.userId)]\n);\n\nexport const account = pgTable(\n\t'account',\n\t{\n\t\tid: text('id').primaryKey(),\n\t\taccountId: text('account_id').notNull(),\n\t\tproviderId: text('provider_id').notNull(),\n\t\tuserId: text('user_id')\n\t\t\t.notNull()\n\t\t\t.references(() => user.id, { onDelete: 'cascade' }),\n\t\taccessToken: text('access_token'),\n\t\trefreshToken: text('refresh_token'),\n\t\tidToken: text('id_token'),\n\t\taccessTokenExpiresAt: timestamp('access_token_expires_at', { withTimezone: true }),\n\t\trefreshTokenExpiresAt: timestamp('refresh_token_expires_at', { withTimezone: true }),\n\t\tscope: text('scope'),\n\t\tpassword: text('password'),\n\t\tcreatedAt: timestamp('created_at', { withTimezone: true })\n\t\t\t.default(sql`now()`)\n\t\t\t.notNull(),\n\t\tupdatedAt: timestamp('updated_at', { withTimezone: true })\n\t\t\t.default(sql`now()`)\n\t\t\t.$onUpdate(() => new Date())\n\t\t\t.notNull()\n\t},\n\t(table) => [index('account_userId_idx').on(table.userId)]\n);\n\nexport const verification = pgTable(\n\t'verification',\n\t{\n\t\tid: text('id').primaryKey(),\n\t\tidentifier: text('identifier').notNull(),\n\t\tvalue: text('value').notNull(),\n\t\texpiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),\n\t\tcreatedAt: timestamp('created_at', { withTimezone: true })\n\t\t\t.default(sql`now()`)\n\t\t\t.notNull(),\n\t\tupdatedAt: timestamp('updated_at', { withTimezone: true })\n\t\t\t.default(sql`now()`)\n\t\t\t.notNull()\n\t},\n\t(table) => [index('verification_identifier_idx').on(table.identifier)]\n);\n\nexport const userRelations = relations(user, ({ many }) => ({\n\tsessions: many(session),\n\taccounts: many(account)\n}));\n\nexport const sessionRelations = relations(session, ({ one }) => ({\n\tuser: one(user, {\n\t\tfields: [session.userId],\n\t\treferences: [user.id]\n\t})\n}));\n\nexport const accountRelations = relations(account, ({ one }) => ({\n\tuser: one(user, {\n\t\tfields: [account.userId],\n\t\treferences: [user.id]\n\t})\n}));\n",
  "/lib/server/db/index.ts": "import { drizzle } from 'drizzle-orm/postgres-js';\nimport postgres from 'postgres';\nimport * as schema from './schema';\nimport { env } from '$env/dynamic/private';\n\nif (!env.DATABASE_URL) throw new Error('DATABASE_URL is not set');\n\nconst client = postgres(env.DATABASE_URL);\n\nexport const db = drizzle(client, { schema });\n",
  "/lib/server/db/schema.ts": "import { pgTable, uuid, text, integer } from 'drizzle-orm/pg-core';\n\nexport const task = pgTable('task', {\n\tid: uuid('id').primaryKey().defaultRandom(),\n\ttitle: text('title').notNull(),\n\tpriority: integer('priority').notNull().default(1)\n});\n\nexport * from './auth.schema';\n",
  "/lib/server/schemas.ts": "import { z } from 'zod';\n\nexport const loginSchema = z.object({\nemail: z.string().email(),\npassword: z.string().min(8)\n});\n\nexport const changePasswordSchema = z.object({\ncurrentPassword: z.string().min(8),\nnewPassword: z.string().min(8)\n});\n\nexport const createUserSchema = z.object({\nname: z.string().min(1),\nemail: z.string().email(),\npassword: z.string().min(8)\n});\n\nexport const updateUserSchema = z.object({\nid: z.string().min(1),\nname: z.string().min(1),\nemail: z.string().email()\n});\n\nexport const deleteUserSchema = z.object({\nid: z.string().min(1)\n});\n\nexport const toggleVerifySchema = z.object({\nid: z.string().min(1),\nverified: z.boolean()\n});\n\nexport const setupSchema = z.object({\nname: z.string().min(1),\nemail: z.string().email(),\npassword: z.string().min(8)\n});\n\nexport type LoginSchema = typeof loginSchema;\nexport type ChangePasswordSchema = typeof changePasswordSchema;\nexport type CreateUserSchema = typeof createUserSchema;\nexport type UpdateUserSchema = typeof updateUserSchema;\nexport type DeleteUserSchema = z.infer<typeof deleteUserSchema>;\nexport type ToggleVerifySchema = typeof toggleVerifySchema;\nexport type SetupSchema = typeof setupSchema;\n",
  "/lib/types.ts": "export type UserRow = {\n\tid: string;\n\tname: string;\n\temail: string;\n\temailVerified: boolean;\n\timage: string | null;\n\tcreatedAt: Date | null;\n};\n",
  "/playwright.config.ts": "import { defineConfig, devices } from '@playwright/test';\n\n/**\n * Playwright configuration for the SVForge dashboard.\n *\n * This is an opt-in testing profile — install Playwright separately:\n *   bun add -D @playwright/test\n *   bunx playwright install\n *\n * Then run: bunx playwright test\n */\nexport default defineConfig({\n\ttestDir: './e2e',\n\tfullyParallel: true,\n\tforbidOnly: !!process.env.CI,\n\tretries: process.env.CI ? 2 : 0,\n\tworkers: process.env.CI ? 1 : undefined,\n\treporter: 'html',\n\tuse: {\n\t\tbaseURL: 'http://localhost:4173',\n\t\ttrace: 'on-first-retry',\n\t\t// Dashboard UI copy is i18n via Paraglide; the E2E selectors target the\n\t\t// English strings, so pin the browser locale (#267).\n\t\tlocale: 'en-US'\n\t},\n\tprojects: [\n\t\t{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }\n\t],\n\twebServer: {\n\t\tcommand: 'bun run build && bun run preview',\n\t\turl: 'http://localhost:4173',\n\t\treuseExistingServer: !process.env.CI\n\t}\n});\n",
  "/routes/(app)/+layout.server.ts": "import { redirect } from '@sveltejs/kit';\nimport type { LayoutServerLoad } from './$types';\n\n// Auth guard for the (app) route group.\n// The (app) group wraps all protected routes — unauthenticated users are redirected to /login\n// with a callbackURL so they return here after successful login. — redirects to /login if no session.\n// This template uses single-admin pattern (first user is admin).\n// For multi-user, add a role column and check here.\nexport const load: LayoutServerLoad = async ({ locals, url }) => {\n\tif (!locals.session || !locals.user) {\n\t\tthrow redirect(302, `/login?callbackURL=${encodeURIComponent(url.pathname)}`);\n\t}\n\n\treturn {\n\t\tuser: locals.user,\n\t\tsession: locals.session\n\t};\n};\n",
  "/routes/(app)/+layout.svelte": "<script lang=\"ts\">\n\timport { page } from '$app/state';\n\timport { goto } from '$app/navigation';\n\timport AdminLayout from '$lib/components/svforge/layout/AdminLayout.svelte';\n\timport { authClient } from '$lib/client/auth';\n\n\tlet { data, children } = $props();\n\n\tasync function handleSignOut() {\n\t\tawait authClient.signOut();\n\t\tgoto('/login');\n\t}\n</script>\n\n<AdminLayout currentPath={page.url.pathname} user={data.user} onSignOut={handleSignOut}>\n\t{@render children()}\n</AdminLayout>\n",
  "/routes/(app)/admin/+page.server.ts": "import { redirect } from '@sveltejs/kit';\nimport { db } from '$lib/server/db';\nimport { user, session } from '$lib/server/db/schema';\nimport { sql, desc, asc } from 'drizzle-orm';\nimport { isAdmin } from '$lib/server/admin';\nimport type { PageServerLoad } from './$types';\n\nexport const load: PageServerLoad = async ({ locals }) => {\n\tif (!locals.user || !(await isAdmin(locals.user.id))) {\n\t\tthrow redirect(302, '/login');\n\t}\n\n\tconst [totalUsersResult] = await db.select({ count: sql<number>`count(*)` }).from(user);\n\tconst [activeSessionsResult] = await db.select({ count: sql<number>`count(*)` }).from(session).where(sql`expires_at > now()`);\n\tconst [newThisWeekResult] = await db.select({ count: sql<number>`count(*)` }).from(user).where(sql`created_at > now() - interval '7 days'`);\n\n\tconst recentUsers = await db.select({\n\t\tid: user.id,\n\t\tname: user.name,\n\t\temail: user.email,\n\t\temailVerified: user.emailVerified,\n\t\tcreatedAt: user.createdAt\n\t}).from(user).orderBy(desc(user.createdAt)).limit(5);\n\n\treturn {\n\t\tuser: locals.user,\n\t\tstats: {\n\t\t\ttotalUsers: totalUsersResult?.count ?? 0,\n\t\t\tactiveSessions: activeSessionsResult?.count ?? 0,\n\t\t\tnewThisWeek: newThisWeekResult?.count ?? 0\n\t\t},\n\t\trecentUsers\n\t};\n};\n",
  "/routes/(app)/admin/+page.svelte": "<script lang=\"ts\">\n\timport * as m from '$lib/paraglide/messages.js';\n\timport { Card, AvatarInitial } from '$lib/components/svforge/ui';\n\timport { Badge } from '$lib/components/svforge/primitives';\n\timport { Button } from '$lib/components/svforge/primitives';\n\timport Users from 'phosphor-svelte/lib/Users';\n\timport ChartBar from 'phosphor-svelte/lib/ChartBar';\n\timport Clock from 'phosphor-svelte/lib/Clock';\n\n\tlet { data } = $props();\n</script>\n\n<svelte:head>\n\t<title>{m.admin_title()}</title>\n</svelte:head>\n\n<div class=\"space-y-section\">\n\t<div class=\"flex items-center justify-between\">\n\t\t<div>\n\t\t\t<h2 class=\"text-2xl font-heading font-bold\">{m.admin_dashboard()}</h2>\n\t\t\t<p class=\"text-surface-500\">{m.admin_welcome_back({ name: data.user.name })}</p>\n\t\t</div>\n\t\t<Button href=\"/admin/users\" size=\"sm\">\n\t\t\t<Users size={16} class=\"mr-1\" />\n\t\t\t{m.admin_manage_users()}\n\t\t</Button>\n\t</div>\n\n\t<!-- Stats -->\n\t<div class=\"grid grid-cols-1 sm:grid-cols-3 gap-group\">\n\t\t<Card variant=\"elevated\">\n\t\t\t<div class=\"flex items-center gap-3\">\n\t\t\t\t<div class=\"p-3 rounded-card bg-primary-100-900\">\n\t\t\t\t\t<Users size={24} class=\"text-primary-600-400\" />\n\t\t\t\t</div>\n\t\t\t\t<div>\n\t\t\t\t\t<p class=\"text-sm text-surface-500\">{m.admin_total_users()}</p>\n\t\t\t\t\t<p class=\"text-2xl font-heading font-bold\">{data.stats.totalUsers}</p>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</Card>\n\t\t<Card variant=\"elevated\">\n\t\t\t<div class=\"flex items-center gap-3\">\n\t\t\t\t<div class=\"p-3 rounded-card bg-success-100-900\">\n\t\t\t\t\t<Clock size={24} class=\"text-success-600\" />\n\t\t\t\t</div>\n\t\t\t\t<div>\n\t\t\t\t\t<p class=\"text-sm text-surface-500\">{m.admin_active_sessions()}</p>\n\t\t\t\t\t<p class=\"text-2xl font-heading font-bold\">{data.stats.activeSessions}</p>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</Card>\n\t\t<Card variant=\"elevated\">\n\t\t\t<div class=\"flex items-center gap-3\">\n\t\t\t\t<div class=\"p-3 rounded-card bg-secondary-100-900\">\n\t\t\t\t\t<ChartBar size={24} class=\"text-secondary-600-400\" />\n\t\t\t\t</div>\n\t\t\t\t<div>\n\t\t\t\t\t<p class=\"text-sm text-surface-500\">{m.admin_this_week()}</p>\n\t\t\t\t\t<p class=\"text-2xl font-heading font-bold\">{data.stats.newThisWeek}</p>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</Card>\n\t</div>\n\n\t<!-- Recent Users -->\n\t<Card>\n\t\t{#snippet header()}\n\t\t\t<h3 class=\"font-heading font-bold\">{m.admin_recent_users()}</h3>\n\t\t{/snippet}\n\n\t\t<div class=\"space-y-3\">\n\t\t\t{#each data.recentUsers as u (u.id)}\n\t\t\t\t<div class=\"flex items-center justify-between py-2 border-b border-surface-100-800 last:border-0\">\n\t\t\t\t\t<div class=\"flex items-center gap-3\">\n\t\t\t\t\t\t<AvatarInitial name={u.name} />\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<p class=\"font-medium text-sm\">{u.name}</p>\n\t\t\t\t\t\t\t<p class=\"text-xs text-surface-500\">{u.email}</p>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t\t<Badge color={u.emailVerified ? 'success' : 'warning'}>\n\t\t\t\t\t\t{u.emailVerified ? m.admin_verified() : m.admin_pending()}\n\t\t\t\t\t</Badge>\n\t\t\t\t</div>\n\t\t\t{/each}\n\t\t</div>\n\t</Card>\n</div>\n",
  "/routes/(app)/admin/settings/+page.server.ts": "import { auth } from '$lib/server/auth';\nimport { changePasswordSchema } from '$lib/server/schemas';\nimport { fail, type Actions } from '@sveltejs/kit';\nimport type { PageServerLoad } from './$types';\n\nexport const load: PageServerLoad = async ({ locals }) => {\n\treturn {\n\t\tuser: locals.user!\n\t};\n};\n\nexport const actions: Actions = {\n\tchangePassword: async ({ request }) => {\n\t\tconst formData = await request.formData();\n\t\tconst parsed = changePasswordSchema.safeParse({\n\t\t\tcurrentPassword: formData.get('currentPassword'),\n\t\t\tnewPassword: formData.get('newPassword')\n\t\t});\n\n\t\tif (!parsed.success) {\n\t\t\treturn fail(400, { message: parsed.error.issues[0]?.message ?? 'Invalid input' });\n\t\t}\n\n\t\tconst { currentPassword, newPassword } = parsed.data;\n\n\t\ttry {\n\t\t\tawait auth.api.changePassword({\n\t\t\t\theaders: request.headers,\n\t\t\t\tbody: { currentPassword, newPassword }\n\t\t\t});\n\t\t\treturn { success: true };\n\t\t} catch {\n\t\t\t// Generic message — never leak e.message internals to the UI (#188).\n\t\t\treturn fail(400, { message: 'Failed to change password' });\n\t\t}\n\t}\n};\n",
  "/routes/(app)/admin/settings/+page.svelte": "<script lang=\"ts\">\n\timport { enhance } from '$app/forms';\n\timport * as m from '$lib/paraglide/messages.js';\n\timport { Card, AvatarInitial, Feedback } from '$lib/components/svforge/ui';\n\timport { Button, Input } from '$lib/components/svforge/primitives';\n\timport Lock from 'phosphor-svelte/lib/Lock';\n\timport type { ActionData } from './$types';\n\n\tlet { data, form }: { data: { user: { id: string; name: string; email: string } | null }, form: ActionData } = $props();\n\tlet currentPassword = $state('');\n\tlet newPassword = $state('');\n\tlet confirmPassword = $state('');\n\n\t// Client-side validation — cleared on form response, not via $effect\n\tlet validationError = $state('');\n</script>\n\n<svelte:head>\n\t<title>{m.settings_title()}</title>\n</svelte:head>\n\n<div class=\"space-y-section max-w-2xl\">\n\t<h2 class=\"text-2xl font-heading font-bold\">{m.settings_heading()}</h2>\n\n\t<!-- Profile info -->\n\t<Card>\n\t\t{#snippet header()}\n\t\t\t<h3 class=\"font-heading font-bold\">{m.settings_profile()}</h3>\n\t\t{/snippet}\n\t\t<div class=\"space-y-3\">\n\t\t\t<div class=\"flex items-center gap-4\">\n\t\t\t\t<AvatarInitial name={data.user?.name ?? ''} size=\"lg\" />\n\t\t\t\t<div>\n\t\t\t\t\t<p class=\"font-medium\">{data.user?.name}</p>\n\t\t\t\t\t<p class=\"text-sm text-surface-500\">{data.user?.email}</p>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</div>\n\t</Card>\n\n\t<!-- Change password -->\n\t<Card>\n\t\t{#snippet header()}\n\t\t\t<div class=\"flex items-center gap-2\">\n\t\t\t\t<Lock size={18} />\n\t\t\t\t<h3 class=\"font-heading font-bold\">{m.settings_change_password()}</h3>\n\t\t\t</div>\n\t\t{/snippet}\n\n\t\t{#if form?.message}\n\t\t\t<Feedback type={form.success ? 'success' : 'error'} message={form.message} class=\"mb-4\" />\n\t\t{/if}\n\t\t{#if validationError}\n\t\t\t<div class=\"mb-4 p-3 rounded-card text-sm bg-error-100-900 text-error-300-700\">\n\t\t\t\t{validationError}\n\t\t\t</div>\n\t\t{/if}\n\n\t\t<form method=\"POST\" action=\"?/changePassword\" onsubmit={(e) => {\n\t\t\t\tif (newPassword !== confirmPassword) {\n\t\t\t\t\te.preventDefault();\n\t\t\t\t\tvalidationError = m.settings_password_mismatch();\n\t\t\t\t} else {\n\t\t\t\t\tvalidationError = '';\n\t\t\t\t}\n\t\t\t}} use:enhance class=\"space-y-4\">\n\t\t\t<Input label={m.settings_current_password()} type=\"password\" name=\"currentPassword\" bind:value={currentPassword} required />\n\t\t\t<Input label={m.settings_new_password()} type=\"password\" name=\"newPassword\" bind:value={newPassword} placeholder={m.common_min_chars()} required />\n\t\t\t<Input label={m.settings_confirm_password()} type=\"password\" name=\"confirmPassword\" bind:value={confirmPassword} required />\n\t\t\t<div class=\"flex justify-end\">\n\t\t\t\t<Button type=\"submit\">{m.settings_update_password()}</Button>\n\t\t\t</div>\n\t\t</form>\n\t</Card>\n</div>\n",
  "/routes/(app)/admin/users/+page.server.ts": "import { db } from '$lib/server/db';\nimport { user, account, session } from '$lib/server/db/schema';\nimport { desc, eq } from 'drizzle-orm';\nimport { fail, redirect, error, type Actions } from '@sveltejs/kit';\nimport { isAdmin } from '$lib/server/admin';\nimport { createCredentialUser, DuplicateEmailError } from '$lib/server/admin-users';\nimport { createUserSchema, updateUserSchema, deleteUserSchema, toggleVerifySchema } from '$lib/server/schemas';\nimport type { PageServerLoad } from './$types';\nimport type { RequestEvent } from '@sveltejs/kit';\n\n/**\n * Require an authenticated admin user for a form action.\n * Returns the user id on success, or throws a 401/403 error.\n *\n * Every admin action must call this BEFORE reading formData or touching the db.\n */\nasync function requireAdmin(event: RequestEvent): Promise<string> {\n\tif (!event.locals.user) {\n\t\tthrow error(401, { message: 'Authentication required' });\n\t}\n\tif (!(await isAdmin(event.locals.user.id))) {\n\t\tthrow error(403, { message: 'Admin access required' });\n\t}\n\treturn event.locals.user.id;\n}\n\nexport const load: PageServerLoad = async ({ locals }) => {\n\tif (!locals.user || !(await isAdmin(locals.user.id))) {\n\t\tthrow redirect(302, '/login');\n\t}\n\n\tconst users = await db.select({\n\t\tid: user.id,\n\t\tname: user.name,\n\t\temail: user.email,\n\t\temailVerified: user.emailVerified,\n\t\timage: user.image,\n\t\tcreatedAt: user.createdAt\n\t}).from(user).orderBy(desc(user.createdAt));\n\n\treturn { users };\n};\n\n/**\n * Form actions (#295) — golden reference for SvelteKit mutations.\n *\n * Every action returns a STABLE machine-readable `code` instead of English\n * copy: the UI maps codes to Paraglide FR/EN messages, so no visible text\n * comes from the server and the copy can never leak internal details.\n */\n\nexport const actions: Actions = {\n\tcreate: async (event) => {\n\t\tawait requireAdmin(event);\n\t\tconst { request } = event;\n\t\tconst formData = await request.formData();\n\t\tconst parsed = createUserSchema.safeParse({\n\t\t\tname: formData.get('name'),\n\t\t\temail: formData.get('email'),\n\t\t\tpassword: formData.get('password')\n\t\t});\n\n\t\tif (!parsed.success) {\n\t\t\treturn fail(400, { code: 'invalid_input' });\n\t\t}\n\n\t\tconst { name, email, password } = parsed.data;\n\n\t\ttry {\n\t\t\t// Contract-compliant credential user: lowercase email, accountId = userId,\n\t\t\t// user + credential account created atomically, admin session untouched.\n\t\t\t// (signUpEmail is NOT used: it sets a session cookie for the new user,\n\t\t\t// which would silently replace the admin's own session.)\n\t\t\tawait createCredentialUser({ name, email, password });\n\t\t} catch (error) {\n\t\t\tif (error instanceof DuplicateEmailError) {\n\t\t\t\treturn fail(400, { code: 'email_exists' });\n\t\t\t}\n\t\t\t// Generic code — never leak e.message internals to the UI (#188).\n\t\t\treturn fail(500, { code: 'create_failed' });\n\t\t}\n\n\t\treturn { success: true, code: 'created' };\n\t},\n\n\tupdate: async (event) => {\n\t\tawait requireAdmin(event);\n\t\tconst { request } = event;\n\t\tconst formData = await request.formData();\n\t\tconst parsed = updateUserSchema.safeParse({\n\t\t\tid: formData.get('id'),\n\t\t\tname: formData.get('name'),\n\t\t\temail: formData.get('email')\n\t\t});\n\n\t\tif (!parsed.success) {\n\t\t\treturn fail(400, { code: 'invalid_input' });\n\t\t}\n\n\t\tconst { id, name, email } = parsed.data;\n\t\tconst normalizedEmail = email.toLowerCase();\n\n\t\t// Check email not taken by another user (case-insensitive, matching the\n\t\t// lowercase credential contract of the create helper — #292).\n\t\tconst [existing] = await db\n\t\t\t.select({ id: user.id })\n\t\t\t.from(user)\n\t\t\t.where(eq(user.email, normalizedEmail))\n\t\t\t.limit(1);\n\t\tif (existing && existing.id !== id) {\n\t\t\treturn fail(400, { code: 'email_taken' });\n\t\t}\n\n\t\ttry {\n\t\t\tawait db.update(user).set({\n\t\t\t\tname,\n\t\t\t\temail: normalizedEmail,\n\t\t\t\tupdatedAt: new Date()\n\t\t\t}).where(eq(user.id, id));\n\t\t} catch {\n\t\t\t// Generic code — never leak e.message internals to the UI (#188).\n\t\t\treturn fail(500, { code: 'update_failed' });\n\t\t}\n\n\t\treturn { success: true, code: 'updated' };\n\t},\n\n\tdelete: async (event) => {\n\t\tconst adminId = await requireAdmin(event);\n\t\tconst { request } = event;\n\t\tconst formData = await request.formData();\n\t\tconst parsed = deleteUserSchema.safeParse({\n\t\t\tid: formData.get('id')\n\t\t});\n\n\t\tif (!parsed.success) {\n\t\t\treturn fail(400, { code: 'invalid_input' });\n\t\t}\n\n\t\tconst { id } = parsed.data;\n\n\t\t// Prevent self-delete\n\t\tif (id === adminId) {\n\t\t\treturn fail(400, { code: 'self_delete' });\n\t\t}\n\n\t\t// Verify the target user exists before attempting deletion\n\t\tconst [target] = await db.select({ id: user.id }).from(user).where(eq(user.id, id)).limit(1);\n\t\tif (!target) {\n\t\t\treturn fail(404, { code: 'not_found' });\n\t\t}\n\n\t\t// Atomic deletion: session → account → user (FK-safe order)\n\t\t// All deletions succeed or none do.\n\t\ttry {\n\t\t\tawait db.transaction(async (tx) => {\n\t\t\t\tawait tx.delete(session).where(eq(session.userId, id));\n\t\t\t\tawait tx.delete(account).where(eq(account.userId, id));\n\t\t\t\tawait tx.delete(user).where(eq(user.id, id));\n\t\t\t});\n\t\t} catch {\n\t\t\t// Generic code — never leak e.message internals to the UI (#188).\n\t\t\treturn fail(500, { code: 'delete_failed' });\n\t\t}\n\n\t\treturn { success: true, code: 'deleted' };\n\t},\n\n\ttoggleVerify: async (event) => {\n\t\tawait requireAdmin(event);\n\t\tconst { request } = event;\n\t\tconst formData = await request.formData();\n\t\tconst parsed = toggleVerifySchema.safeParse({\n\t\t\tid: formData.get('id'),\n\t\t\tverified: formData.get('verified') === 'true'\n\t\t});\n\n\t\tif (!parsed.success) {\n\t\t\treturn fail(400, { code: 'invalid_input' });\n\t\t}\n\n\t\tconst { id, verified } = parsed.data;\n\n\t\ttry {\n\t\t\tawait db.update(user).set({\n\t\t\t\temailVerified: !verified,\n\t\t\t\tupdatedAt: new Date()\n\t\t\t}).where(eq(user.id, id));\n\t\t} catch {\n\t\t\t// Generic code — never leak e.message internals to the UI (#188).\n\t\t\treturn fail(500, { code: 'verify_failed' });\n\t\t}\n\n\t\treturn { success: true, code: verified ? 'unverified' : 'verified' };\n\t}\n};\n",
  "/routes/(app)/admin/users/+page.svelte": "<script lang=\"ts\">\n\timport type { PageData } from './$types';\n\timport { page } from '$app/state';\n\timport { enhance } from '$app/forms';\n\timport type { SubmitFunction } from '@sveltejs/kit';\n\timport * as m from '$lib/paraglide/messages.js';\n\timport { Card, AvatarInitial, Feedback, Table } from '$lib/components/svforge/ui';\n\timport { Badge } from '$lib/components/svforge/primitives';\n\timport { Button, Input } from '$lib/components/svforge/primitives';\n\timport type { UserRow } from '$lib/types';\n\timport UserPlus from 'phosphor-svelte/lib/UserPlus';\n\timport Trash from 'phosphor-svelte/lib/Trash';\n\timport Pencil from 'phosphor-svelte/lib/Pencil';\n\timport X from 'phosphor-svelte/lib/X';\n\n\tlet { data }: { data: PageData } = $props();\n\tlet currentUserId = $derived(page.data.user?.id);\n\n\tlet search = $state('');\n\tlet feedback = $state<{ type: 'success' | 'error'; message: string } | null>(null);\n\n\t// Modal state\n\tlet modal = $state<'create' | 'edit' | 'delete' | null>(null);\n\tlet editUser = $state<{ id: string; name: string; email: string } | null>(null);\n\tlet deleteTarget = $state<{ id: string; name: string } | null>(null);\n\n\t// Form fields\n\tlet formName = $state('');\n\tlet formEmail = $state('');\n\tlet formPassword = $state('');\n\n\t// Table slot receives rows as Record<string, unknown> — recover the row type.\n\tfunction asUser(row: Record<string, unknown>): UserRow {\n\t\treturn row as unknown as UserRow;\n\t}\n\n\t// Columns are re-derived so Paraglide labels stay reactive to the locale.\n\tlet columns = $derived([\n\t\t{ key: 'name', label: m.users_name() },\n\t\t{ key: 'email', label: m.users_email(), class: 'hidden sm:table-cell' },\n\t\t{ key: 'status', label: m.users_status() },\n\t\t{ key: 'actions', label: m.users_actions(), class: 'text-right' }\n\t]);\n\n\tlet filtered = $derived(\n\t\tdata.users.filter((u) =>\n\t\t\tu.name.toLowerCase().includes(search.toLowerCase()) ||\n\t\t\tu.email.toLowerCase().includes(search.toLowerCase())\n\t\t)\n\t);\n\n\tfunction openCreate() {\n\t\tformName = '';\n\t\tformEmail = '';\n\t\tformPassword = '';\n\t\tmodal = 'create';\n\t}\n\n\tfunction openEdit(u: { id: string; name: string; email: string }) {\n\t\teditUser = { id: u.id, name: u.name, email: u.email };\n\t\tformName = u.name;\n\t\tformEmail = u.email;\n\t\tmodal = 'edit';\n\t}\n\n\tfunction openDelete(u: { id: string; name: string }) {\n\t\tdeleteTarget = { id: u.id, name: u.name };\n\t\tmodal = 'delete';\n\t}\n\n\tfunction closeModal() {\n\t\tmodal = null;\n\t\teditUser = null;\n\t\tdeleteTarget = null;\n\t}\n\n\t/**\n\t * Stable server codes → localized feedback (#295). The server never sends\n\t * English copy: every visible message is a Paraglide message mapped here.\n\t */\n\tfunction feedbackFor(code: string | undefined, isError: boolean): string {\n\t\tif (!isError) {\n\t\t\tswitch (code) {\n\t\t\t\tcase 'created':\n\t\t\t\t\treturn m.users_created();\n\t\t\t\tcase 'updated':\n\t\t\t\t\treturn m.users_updated();\n\t\t\t\tcase 'deleted':\n\t\t\t\t\treturn m.users_deleted();\n\t\t\t\tcase 'verified':\n\t\t\t\t\treturn m.users_verified_ok();\n\t\t\t\tcase 'unverified':\n\t\t\t\t\treturn m.users_unverified();\n\t\t\t\tdefault:\n\t\t\t\t\treturn m.users_created();\n\t\t\t}\n\t\t}\n\t\tswitch (code) {\n\t\t\tcase 'email_exists':\n\t\t\t\treturn m.users_email_exists();\n\t\t\tcase 'email_taken':\n\t\t\t\treturn m.users_email_taken();\n\t\t\tcase 'self_delete':\n\t\t\t\treturn m.users_self_delete();\n\t\t\tcase 'not_found':\n\t\t\t\treturn m.users_not_found();\n\t\t\tcase 'invalid_input':\n\t\t\t\treturn m.users_invalid_input();\n\t\t\tcase 'create_failed':\n\t\t\t\treturn m.users_created_failed();\n\t\t\tcase 'update_failed':\n\t\t\t\treturn m.users_updated_failed();\n\t\t\tcase 'delete_failed':\n\t\t\t\treturn m.users_deleted_failed();\n\t\t\tcase 'verify_failed':\n\t\t\t\treturn m.users_verify_failed();\n\t\t\tdefault:\n\t\t\t\treturn m.users_created_failed();\n\t\t}\n\t}\n\n\t/**\n\t * Standard SvelteKit use:enhance handler (#295) — the golden reference for\n\t * form mutations: `deserialize` + `applyAction` are handled by `enhance`,\n\t * the action result is a typed ActionResult (success/failure/redirect/error)\n\t * and no imperative fetch parsing exists anywhere.\n\t */\n\tconst submitEnhance: SubmitFunction = () => {\n\t\treturn async ({ result, update }) => {\n\t\t\tif (result.type === 'success') {\n\t\t\t\tfeedback = { type: 'success', message: feedbackFor(result.data?.code, false) };\n\t\t\t\tcloseModal();\n\t\t\t\t// update() applies the response, resets the form and invalidates the\n\t\t\t\t// page data (standard applyAction behaviour).\n\t\t\t\tawait update({ reset: true });\n\t\t\t} else if (result.type === 'failure') {\n\t\t\t\tfeedback = { type: 'error', message: feedbackFor(result.data?.code, true) };\n\t\t\t} else if (result.type === 'redirect' || result.type === 'error') {\n\t\t\t\t// SvelteKit handles redirects and errors natively via applyAction.\n\t\t\t\tawait update();\n\t\t\t}\n\t\t};\n\t};\n</script>\n\n<svelte:head>\n\t<title>{m.users_title()}</title>\n</svelte:head>\n\n<div class=\"space-y-group\">\n\t<div class=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3\">\n\t\t<h2 class=\"text-2xl font-heading font-bold\">{m.users_heading()}</h2>\n\t\t<Button onclick={openCreate}>\n\t\t\t<UserPlus size={16} class=\"mr-1\" />\n\t\t\t{m.users_add()}\n\t\t</Button>\n\t</div>\n\n\t{#if feedback}\n\t\t<Feedback type={feedback.type} message={feedback.message} ondismiss={() => (feedback = null)} />\n\t{/if}\n\n\t<Input placeholder={m.users_search_placeholder()} bind:value={search} />\n\n\t<!-- CRUD data table: SvelteForge Table primitive (golden reference) -->\n\t<Table {columns} rows={filtered}>\n\t\t{#snippet children({ row, col })}\n\t\t\t{#if col.key === 'name'}\n\t\t\t\t{@const user = asUser(row)}\n\t\t\t\t<div class=\"flex items-center gap-3\">\n\t\t\t\t\t<AvatarInitial name={user.name} size=\"sm\" />\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<p class=\"font-medium\">{user.name}</p>\n\t\t\t\t\t\t<p class=\"text-xs text-surface-500 sm:hidden\">{user.email}</p>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t{:else if col.key === 'status'}\n\t\t\t\t{@const user = asUser(row)}\n\t\t\t\t<!-- toggleVerify is a real form action too (#295): hidden inputs carry\n\t\t\t\t     the id and the current state, use:enhance handles the result. -->\n\t\t\t\t<form method=\"POST\" action=\"?/toggleVerify\" use:enhance={submitEnhance}>\n\t\t\t\t\t<input type=\"hidden\" name=\"id\" value={user.id} />\n\t\t\t\t\t<input type=\"hidden\" name=\"verified\" value={String(user.emailVerified)} />\n\t\t\t\t\t<button type=\"submit\" class=\"inline-flex\" aria-label={user.emailVerified ? m.users_pending() : m.users_verified()}>\n\t\t\t\t\t\t<Badge color={user.emailVerified ? 'success' : 'warning'}>\n\t\t\t\t\t\t\t{user.emailVerified ? m.users_verified() : m.users_pending()}\n\t\t\t\t\t\t</Badge>\n\t\t\t\t\t</button>\n\t\t\t\t</form>\n\t\t\t{:else if col.key === 'actions'}\n\t\t\t\t{@const user = asUser(row)}\n\t\t\t\t<div class=\"flex items-center justify-end gap-1\">\n\t\t\t\t\t<button class=\"btn preset-tonal-surface p-2 rounded\" onclick={() => openEdit(user)} aria-label={m.users_edit()}>\n\t\t\t\t\t\t<Pencil size={16} />\n\t\t\t\t\t</button>\n\t\t\t\t\t<button class=\"btn preset-tonal-error p-2 rounded\" onclick={() => openDelete(user)} disabled={user.id === currentUserId} aria-label={m.users_delete()}>\n\t\t\t\t\t\t<Trash size={16} />\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t{/if}\n\t\t{/snippet}\n\t</Table>\n\n\t{#if filtered.length === 0}\n\t\t<p class=\"text-center text-surface-500 py-section\">{m.users_none()}</p>\n\t{/if}\n</div>\n\n<!-- Modal overlay -->\n{#if modal}\n\t<div class=\"fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-element\" role=\"presentation\" onclick={closeModal}>\n\t\t<Card class=\"w-full max-w-modal\" onclick={(e: Event) => e.stopPropagation()}>\n\t\t\t<div class=\"flex items-center justify-between mb-4\">\n\t\t\t\t<h3 class=\"text-lg font-heading font-bold\">\n\t\t\t\t\t{modal === 'create' ? m.users_modal_create() : modal === 'edit' ? m.users_modal_edit() : m.users_modal_delete()}\n\t\t\t\t</h3>\n\t\t\t\t<button class=\"btn preset-tonal-surface p-1 rounded\" onclick={closeModal} aria-label={m.users_close()}>\n\t\t\t\t\t<X size={18} />\n\t\t\t\t</button>\n\t\t\t</div>\n\n\t\t\t{#if modal === 'create' || modal === 'edit'}\n\t\t\t\t<!-- Real SvelteKit form action (#295): method=POST + action=?/create|?/update,\n\t\t\t\t     use:enhance handles deserialize/applyAction. No fetch().json() anywhere. -->\n\t\t\t\t<form\n\t\t\t\t\tmethod=\"POST\"\n\t\t\t\t\taction={modal === 'create' ? '?/create' : '?/update'}\n\t\t\t\t\tuse:enhance={submitEnhance}\n\t\t\t\t\tclass=\"space-y-4\"\n\t\t\t\t>\n\t\t\t\t\t{#if modal === 'edit' && editUser}\n\t\t\t\t\t\t<input type=\"hidden\" name=\"id\" value={editUser.id} />\n\t\t\t\t\t{/if}\n\t\t\t\t\t<Input label={m.users_label_name()} name=\"name\" bind:value={formName} placeholder={m.users_placeholder_name()} required />\n\t\t\t\t\t<Input label={m.users_label_email()} name=\"email\" type=\"email\" bind:value={formEmail} placeholder={m.users_placeholder_email()} required />\n\t\t\t\t\t{#if modal === 'create'}\n\t\t\t\t\t\t<Input label={m.users_label_password()} name=\"password\" type=\"password\" bind:value={formPassword} placeholder={m.common_min_chars()} required />\n\t\t\t\t\t{/if}\n\t\t\t\t\t<div class=\"flex justify-end gap-2 pt-2\">\n\t\t\t\t\t\t<Button variant=\"ghost\" type=\"button\" onclick={closeModal}>{m.common_cancel()}</Button>\n\t\t\t\t\t\t<Button type=\"submit\">{modal === 'create' ? m.users_create() : m.common_save()}</Button>\n\t\t\t\t\t</div>\n\t\t\t\t</form>\n\t\t\t{:else if modal === 'delete' && deleteTarget}\n\t\t\t\t<p class=\"text-surface-500 mb-4\">\n\t\t\t\t\t{m.users_delete_confirm({ name: deleteTarget.name })}\n\t\t\t\t</p>\n\t\t\t\t<form method=\"POST\" action=\"?/delete\" use:enhance={submitEnhance}>\n\t\t\t\t\t<input type=\"hidden\" name=\"id\" value={deleteTarget.id} />\n\t\t\t\t\t<div class=\"flex justify-end gap-2\">\n\t\t\t\t\t\t<Button variant=\"ghost\" type=\"button\" onclick={closeModal}>{m.common_cancel()}</Button>\n\t\t\t\t\t\t<Button color=\"error\" type=\"submit\">{m.users_delete_btn()}</Button>\n\t\t\t\t\t</div>\n\t\t\t\t</form>\n\t\t\t{/if}\n\t\t</Card>\n\t</div>\n{/if}\n",
  "/routes/(app)/admin/users/page.server.test.ts": "import { describe, it, expect, vi, beforeEach } from 'vitest';\n\n// Mock the server modules\nvi.mock('$lib/server/db', () => {\n\tconst mockQuery = {\n\t\tselect: vi.fn(() => mockQuery),\n\t\tfrom: vi.fn(() => mockQuery),\n\t\twhere: vi.fn(() => mockQuery),\n\t\tlimit: vi.fn(() => []),\n\t\torderBy: vi.fn(() => []),\n\t\tinsert: vi.fn(() => ({ values: vi.fn() })),\n\t\tupdate: vi.fn(() => ({ set: vi.fn(() => ({ where: vi.fn() })) })),\n\t\tdelete: vi.fn(() => ({ where: vi.fn() })),\n\t\ttransaction: vi.fn(async (cb: Function) => cb({\n\t\t\tdelete: vi.fn(() => ({ where: vi.fn() }))\n\t\t}))\n\t};\n\treturn { db: mockQuery };\n});\n\nvi.mock('$lib/server/db/schema', () => ({\n\tuser: { id: 'id', email: 'email', name: 'name' },\n\taccount: { userId: 'userId' },\n\tsession: { userId: 'userId' }\n}));\n\nvi.mock('$lib/server/admin', () => ({\n\tisAdmin: vi.fn()\n}));\n\nvi.mock('better-auth/crypto', () => ({\n\thashPassword: vi.fn(() => 'hashed-pw')\n}));\n\nvi.mock('drizzle-orm', () => ({\n\tdesc: vi.fn(),\n\teq: vi.fn()\n}));\n\n/**\n * Tests for the admin users page server — authorization, validation,\n * and user management actions.\n */\ndescribe('admin users +page.server — authorization', () => {\n\tbeforeEach(() => {\n\t\tvi.clearAllMocks();\n\t});\n\n\tit('rejects non-admin users with 403', async () => {\n\t\tconst { isAdmin } = await import('$lib/server/admin');\n\t\tvi.mocked(isAdmin).mockResolvedValue(false);\n\n\t\tconst mod = await import('./+page.server');\n\t\tawait expect(\n\t\t\tmod.actions.create({\n\t\t\t\tlocals: { user: { id: 'nonadmin' } },\n\t\t\t\trequest: new Request('http://test', { method: 'POST' })\n\t\t\t} as any)\n\t\t).rejects.toThrow();\n\t});\n\n\tit('rejects anonymous users with 401', async () => {\n\t\tconst mod = await import('./+page.server');\n\t\tawait expect(\n\t\t\tmod.actions.update({\n\t\t\t\tlocals: { user: null },\n\t\t\t\trequest: new Request('http://test', { method: 'POST' })\n\t\t\t} as any)\n\t\t).rejects.toThrow();\n\t});\n});\n\ndescribe('admin users +page.server — validation', () => {\n\tbeforeEach(() => {\n\t\tvi.clearAllMocks();\n\t});\n\n\tit('returns 400 for missing fields on create', async () => {\n\t\tconst { isAdmin } = await import('$lib/server/admin');\n\t\tvi.mocked(isAdmin).mockResolvedValue(true);\n\n\t\tconst mod = await import('./+page.server');\n\t\tconst formData = new FormData();\n\t\t// Missing name and password\n\t\tformData.set('email', 'test@test.com');\n\n\t\tconst result = await mod.actions.create({\n\t\t\tlocals: { user: { id: 'admin1' } },\n\t\t\trequest: { formData: async () => formData }\n\t\t} as any);\n\n\t\texpect((result as { status: number }).status).toBe(400);\n\t});\n});\n\ndescribe('admin users +page.server — user management', () => {\n\tbeforeEach(() => {\n\t\tvi.clearAllMocks();\n\t});\n\n\tit('allows admin to toggle verification (success)', async () => {\n\t\tconst { isAdmin } = await import('$lib/server/admin');\n\t\tvi.mocked(isAdmin).mockResolvedValue(true);\n\n\t\tconst { db } = await import('$lib/server/db');\n\t\t// Mock that user exists\n\t\t(db.select as any).mockReturnValueOnce({\n\t\t\tfrom: vi.fn(() => ({\n\t\t\t\twhere: vi.fn(() => ({ limit: vi.fn(() => []) })),\n\t\t\t\torderBy: vi.fn(() => [])\n\t\t\t}))\n\t\t});\n\n\t\tconst mod = await import('./+page.server');\n\t\tconst formData = new FormData();\n\t\tformData.set('id', 'user-1');\n\t\tformData.set('verified', 'false');\n\n\t\tconst result = await mod.actions.toggleVerify({\n\t\t\tlocals: { user: { id: 'admin1' } },\n\t\t\trequest: { formData: async () => formData }\n\t\t} as any);\n\n\t\texpect(result).toHaveProperty('success', true);\n\t});\n});\n",
  "/routes/(app)/layout.server.test.ts": "import { describe, it, expect, vi } from 'vitest';\nimport { redirect } from '@sveltejs/kit';\n\n// Mock the server modules so the test can run without a real database.\nvi.mock('$lib/server/db', () => ({\n\tdb: {\n\t\tselect: vi.fn(() => ({ from: vi.fn(() => ({ orderBy: vi.fn(() => []) })) })),\n\t\tinsert: vi.fn(() => ({ values: vi.fn() })),\n\t\tupdate: vi.fn(() => ({ set: vi.fn(() => ({ where: vi.fn() })) })),\n\t\tdelete: vi.fn(() => ({ where: vi.fn() }))\n\t}\n}));\n\nvi.mock('$lib/server/admin', () => ({\n\tisAdmin: vi.fn()\n}));\n\n/**\n * Tests for the (app) layout auth guard.\n * Anonymous users must be redirected to /login.\n */\ndescribe('(app) layout auth guard', () => {\n\tit('redirects anonymous users to /login', async () => {\n\t\tconst { isAdmin } = await import('$lib/server/admin');\n\t\tvi.mocked(isAdmin).mockResolvedValue(false);\n\n\t\t// Simulate an unauthenticated request\n\t\tconst load = (await import('./+layout.server')).load;\n\n\t\tawait expect(\n\t\t\tload({\n\t\t\t\tlocals: { user: null, session: null },\n\t\t\t\turl: new URL('http://localhost/dashboard')\n\t\t\t} as any)\n\t\t).rejects.toThrow();\n\n\t\ttry {\n\t\t\tawait load({\n\t\t\t\tlocals: { user: null, session: null },\n\t\t\t\turl: new URL('http://localhost/dashboard')\n\t\t\t} as any);\n\t\t} catch (e) {\n\t\t\tconst err = e as { status: number; location: string };\n\t\t\texpect(err.status).toBe(302);\n\t\t\texpect(err.location).toMatch(/\\/login/);\n\t\t}\n\t});\n\n\tit('returns user data for authenticated users', async () => {\n\t\tconst { isAdmin } = await import('$lib/server/admin');\n\t\tvi.mocked(isAdmin).mockResolvedValue(true);\n\n\t\tconst load = (await import('./+layout.server')).load;\n\t\tconst result = await load({\n\t\t\tlocals: {\n\t\t\t\tuser: { id: 'u1', name: 'Admin', email: 'admin@test.com' },\n\t\t\t\tsession: { id: 's1', userId: 'u1' }\n\t\t\t},\n\t\t\turl: new URL('http://localhost/dashboard')\n\t\t} as any);\n\n\t\texpect(result).toHaveProperty('user');\n\t\texpect(result).toHaveProperty('session');\n\t});\n});\n",
  "/routes/+layout.svelte": "<script lang=\"ts\">\n\timport './layout.css';\n\timport type { Pathname } from '$app/types';\n\timport { resolve } from '$app/paths';\n\timport { page } from '$app/state';\n\timport { locales, localizeHref } from '$lib/paraglide/runtime';\n\tlet { children } = $props();\n</script>\n\n{@render children()}\n\n<div style=\"display:none\">\n\t{#each locales as locale (locale)}\n\t\t<a href={resolve(localizeHref(page.url.pathname, { locale }) as Pathname)}>{locale}</a>\n\t{/each}\n</div>\n",
  "/routes/+page.server.ts": "import { redirect } from '@sveltejs/kit';\nimport type { PageServerLoad } from './$types';\n\nexport const load: PageServerLoad = async ({ locals }) => {\n\tif (locals.session) {\n\t\tthrow redirect(302, '/admin');\n\t}\n\tthrow redirect(302, '/login');\n};\n",
  "/routes/login/+page.server.ts": "import { redirect } from '@sveltejs/kit';\nimport { auth } from '$lib/server/auth';\nimport { loginSchema } from '$lib/server/schemas';\nimport { fail, type Actions } from '@sveltejs/kit';\nimport type { PageServerLoad } from './$types';\n\nexport const load: PageServerLoad = async ({ locals }) => {\n\tif (locals.session) {\n\t\tthrow redirect(302, '/admin');\n\t}\n};\n\nexport const actions: Actions = {\n\tdefault: async ({ request }) => {\n\t\tconst formData = await request.formData();\n\t\tconst parsed = loginSchema.safeParse({\n\t\t\temail: formData.get('email'),\n\t\t\tpassword: formData.get('password')\n\t\t});\n\n\t\tif (!parsed.success) {\n\t\t\treturn fail(400, { message: parsed.error.issues[0]?.message ?? 'Invalid input' });\n\t\t}\n\n\t\tconst { email, password } = parsed.data;\n\n\t\ttry {\n\t\t\tawait auth.api.signInEmail({\n\t\t\t\tbody: { email, password },\n\t\t\t\theaders: request.headers\n\t\t\t});\n\t\t\treturn { success: true };\n\t\t} catch {\n\t\t\t// Generic message — never leak e.message internals to the UI (#188).\n\t\t\treturn fail(401, { message: 'Invalid credentials' });\n\t\t}\n\t}\n};\n",
  "/routes/login/+page.svelte": "<script lang=\"ts\">\n\timport { enhance } from '$app/forms';\n\timport { goto } from '$app/navigation';\n\timport * as m from '$lib/paraglide/messages.js';\n\timport { Card, Feedback } from '$lib/components/svforge/ui';\n\timport { Button, Input } from '$lib/components/svforge/primitives';\n\timport ThemeToggle from '$lib/components/svforge/ui/ThemeToggle.svelte';\n\timport type { ActionData } from './$types';\n\n\tlet { form }: { form: ActionData } = $props();\n\tlet email = $state('');\n\tlet password = $state('');\n\tlet loading = $state(false);\n</script>\n\n<svelte:head>\n\t<title>{m.login_title()}</title>\n</svelte:head>\n\n<main class=\"min-h-screen flex items-center justify-center bg-surface-50-950 p-element\">\n\t<div class=\"w-full max-w-modal\">\n\t\t<div class=\"flex justify-end mb-4\">\n\t\t\t<ThemeToggle />\n\t\t</div>\n\n\t\t<Card variant=\"elevated\">\n\t\t\t<div class=\"text-center mb-6\">\n\t\t\t\t<h1 class=\"text-2xl font-heading font-bold\">{m.login_welcome_back()}</h1>\n\t\t\t\t<p class=\"text-surface-500 mt-1\">{m.login_signin_hint()}</p>\n\t\t\t</div>\n\n\t\t\t{#if form?.message}\n\t\t\t\t<Feedback type=\"error\" message={form.message} class=\"mb-4\" />\n\t\t\t{/if}\n\n\t\t\t<form method=\"POST\" use:enhance={() => {\n\t\t\t\tloading = true;\n\t\t\t\treturn async ({ update }) => {\n\t\t\t\t\tconst result = await update({ reset: false });\n\t\t\t\t\tloading = false;\n\t\t\t\t\t// eslint-disable-next-line @typescript-eslint/no-explicit-any\n\t\t\t\t\tif ((result as any)?.type === 'success') {\n\t\t\t\t\t\tconst callbackURL = new URLSearchParams(window.location.search).get('callbackURL');\n\t\t\t\t\t\tgoto(callbackURL || '/admin');\n\t\t\t\t\t}\n\t\t\t\t};\n\t\t\t}} class=\"space-y-4\">\n\t\t\t\t<Input label={m.login_label_email()} type=\"email\" name=\"email\" bind:value={email} placeholder={m.login_placeholder_email()} required />\n\t\t\t\t<Input label={m.login_label_password()} type=\"password\" name=\"password\" bind:value={password} placeholder=\"••••••••\" required />\n\t\t\t\t<Button type=\"submit\" class=\"w-full\" disabled={loading}>\n\t\t\t\t\t{loading ? m.login_signing_in() : m.login_sign_in()}\n\t\t\t\t</Button>\n\t\t\t</form>\n\t\t</Card>\n\t</div>\n</main>\n",
  "/routes/setup/+page.server.ts": "import { dev } from '$app/environment';\nimport { fail, redirect } from '@sveltejs/kit';\nimport { auth } from '$lib/server/auth';\nimport { setupSchema } from '$lib/server/schemas';\nimport type { Actions } from './$types';\n\nexport const actions: Actions = {\n\tdefault: async ({ request }) => {\n\t\tif (!dev) {\n\t\t\tthrow redirect(302, '/login');\n\t\t}\n\n\t\tconst formData = await request.formData();\n\t\tconst parsed = setupSchema.safeParse({\n\t\t\tname: formData.get('name'),\n\t\t\temail: formData.get('email'),\n\t\t\tpassword: formData.get('password')\n\t\t});\n\n\t\tif (!parsed.success) {\n\t\t\treturn fail(400, { error: parsed.error.issues[0]?.message ?? 'Invalid input' });\n\t\t}\n\n\t\tconst { name, email, password } = parsed.data;\n\n\t\ttry {\n\t\t\tawait auth.api.signUpEmail({\n\t\t\t\tbody: { name, email, password }\n\t\t\t});\n\t\t} catch {\n\t\t\t// Generic message — never leak e.message internals to the UI (#188).\n\t\t\treturn fail(400, { error: 'Failed to create admin' });\n\t\t}\n\n\t\tthrow redirect(302, '/login');\n\t}\n};\n",
  "/routes/setup/+page.svelte": "<script lang=\"ts\">\n\timport * as m from '$lib/paraglide/messages.js';\n\timport { Card } from '$lib/components/svforge/ui';\n\timport { Button, Input } from '$lib/components/svforge/primitives';\n\timport ThemeToggle from '$lib/components/svforge/ui/ThemeToggle.svelte';\n\timport { enhance } from '$app/forms';\n\timport type { ActionData } from './$types';\n\n\tlet { form }: { form: ActionData } = $props();\n</script>\n\n<svelte:head>\n\t<title>{m.setup_title()}</title>\n</svelte:head>\n\n<main class=\"min-h-screen flex items-center justify-center p-4\">\n\t<div class=\"w-full max-w-sm space-y-6\">\n\t\t<div class=\"text-center space-y-2\">\n\t\t\t<h1 class=\"text-2xl font-heading font-bold\">{m.setup_create_admin()}</h1>\n\t\t\t<p class=\"text-surface-500 text-sm\">{m.setup_hint()}</p>\n\t\t</div>\n\n\t\t<Card>\n\t\t\t<form method=\"POST\" class=\"space-y-4\" use:enhance>\n\t\t\t\t{#if form?.error}\n\t\t\t\t\t<p class=\"text-error-500 text-sm\">{form.error}</p>\n\t\t\t\t{/if}\n\n\t\t\t\t<Input name=\"name\" label={m.users_label_name()} placeholder={m.users_placeholder_name()} required />\n\t\t\t\t<Input name=\"email\" label={m.login_label_email()} type=\"email\" placeholder={m.users_placeholder_email()} required />\n\t\t\t\t<Input name=\"password\" label={m.login_label_password()} type=\"password\" placeholder={m.common_min_chars()} required />\n\t\t\t\t<Button type=\"submit\" class=\"w-full\">{m.setup_submit()}</Button>\n\t\t\t</form>\n\t\t</Card>\n\n\t\t<div class=\"flex justify-center\">\n\t\t\t<ThemeToggle />\n\t\t</div>\n\n\t\t<p class=\"text-center text-xs text-surface-500\">\n\t\t\t{m.setup_dev_only()}\n\t\t</p>\n\t</div>\n</main>\n",
  "/vitest.config.ts": "import { defineConfig } from 'vitest/config';\nimport { svelte } from '@sveltejs/vite-plugin-svelte';\nimport { resolve } from 'node:path';\n\nexport default defineConfig({\n\tplugins: [svelte()],\n\tresolve: {\n\t\talias: {\n\t\t\t// SvelteKit resolves $lib via its own plugin; in a bare vitest\n\t\t\t// environment we must declare it so route tests can import\n\t\t\t// $lib/server/* modules (#258).\n\t\t\t$lib: resolve('src/lib')\n\t\t}\n\t},\n\ttest: {\n\t\tinclude: ['src/**/*.test.ts'],\n\t\tenvironment: 'node'\n\t}\n});\n"
};

export const dashboardRootFiles = {
  "/.env.example": "# Database (PostgreSQL)\n# ─────────────────────────────────────────────────────────────\n# SvelteForge dashboard uses PostgreSQL + Drizzle. Pick one:\n\n# Local PostgreSQL (installed on your machine)\nDATABASE_URL=\"postgres://postgres:postgres@localhost:5432/sf_dashboard\"\n\n# PostgreSQL via Docker (reproducible dev setup)\n#   docker run --name sf-db -e POSTGRES_PASSWORD=postgres -e POSTGRES_DB=sf_dashboard \\\n#     -p 5432:5432 -d postgres:17\n# DATABASE_URL=\"postgres://postgres:postgres@localhost:5432/sf_dashboard\"\n\n# Managed PostgreSQL (Neon / Supabase / Railway / RDS…)\n#   paste the connection string from your provider — it already contains\n#   user, password, host and database.\n# DATABASE_URL=\"postgres://user:password@host:5432/dbname?sslmode=require\"\n\n# Better Auth\nORIGIN=http://localhost:5173\nBETTER_AUTH_SECRET=changeme\n\n# Notes:\n# - Generate a strong secret: openssl rand -base64 32\n# - ORIGIN must match your dev server URL\n# - Create the database first if it doesn't exist:\n#     createdb sf_dashboard\n#   or via Docker: POSTGRES_DB=sf_dashboard in the container env.\n",
  "/drizzle.config.ts": "import { defineConfig } from 'drizzle-kit';\n\nexport default defineConfig({\n\tschema: './src/lib/server/db/schema.ts',\n\tout: './drizzle',\n\tdialect: 'postgresql',\n\tdbCredentials: {\n\t\turl: process.env.DATABASE_URL!\n\t}\n});\n",
  "/scripts/setup.sh": "#!/usr/bin/env bash\nset -euo pipefail\n\necho \"SvelteForge Dashboard Setup (PostgreSQL + Drizzle)\"\n\n# 1. Copy .env.example if .env doesn't exist\nif [ ! -f .env ]; then\n\tcp .env.example .env 2>/dev/null || cat > .env << 'ENV'\nDATABASE_URL=\"postgres://postgres:postgres@localhost:5432/sf_dashboard\"\nORIGIN=http://localhost:5173\nBETTER_AUTH_SECRET=\nENV\n\techo \"Created .env\"\nelse\n\techo \".env already exists\"\nfi\n\n# 2. Generate BETTER_AUTH_SECRET if empty\nif grep -q 'BETTER_AUTH_SECRET=$' .env 2>/dev/null || grep -q 'BETTER_AUTH_SECRET=changeme' .env 2>/dev/null; then\n\tSECRET=$(openssl rand -base64 32)\n\tsed -i.bak \"s|BETTER_AUTH_SECRET=.*|BETTER_AUTH_SECRET=$SECRET|\" .env && rm -f .env.bak\n\techo \"Generated BETTER_AUTH_SECRET\"\nfi\n\n# 3. Push DB schema (PostgreSQL). Needs a reachable DATABASE_URL — see .env.example\necho \"Pushing database schema...\"\nbunx drizzle-kit push --force 2>&1 || echo \"Warning: drizzle-kit push failed (is PostgreSQL running? see .env.example for local/Docker/managed options)\"\n\necho \"\"\necho \"Done! Next steps:\"\necho \"  1. bun dev\"\necho \"  2. http://localhost:5173/setup (dev only, creates first admin)\"\n",
  "/static/robots.txt": "# allow crawling everything by default\nUser-agent: *\nDisallow:\n"
};

